SourceCode.Declaration:
public class UPSVendPriceAdmSmartRound extends RunBase
{
    #DEFINE.CurrentVersion(1)

    #LOCALMACRO.CurrentList
       journalNum
     #ENDMACRO

    UPSVendPriceJournalNum journalNum;

}

Method.Source:
void run()
{
    UPSVendPriceAdmTrans  vendPriceAdmTrans;

    ttsbegin;

    while select forupdate vendPriceAdmTrans
        where vendPriceAdmTrans.JournalNum      == journalNum
           && vendPriceAdmTrans.DefaultRelation == UPSVendPriceType::PriceVendList
    {
        vendPriceAdmTrans.Amount = PriceDiscSmartRounding::smartRound(vendPriceAdmTrans.Amount, Currency::find(vendPriceAdmTrans.Currency));

        if (vendPriceAdmTrans.Amount != vendPriceAdmTrans.orig().Amount)
        {
            vendPriceAdmTrans.DifferentFromPosted = NoYes::Yes;
            vendPriceAdmTrans.update();
        }
    }

    ttscommit;
}

public boolean  unpack(container  _packedClass)
{
    Integer     version = RunBase::getVersion(_packedClass);

    switch (version)
    {
        case #CurrentVersion :
            [version, #CurrentList] = _packedClass;
            break;

        default :
            return false;
    }

    return true;
}

static UPSVendPriceAdmSmartRound construct()
{
    return new UPSVendPriceAdmSmartRound();
}

static void main(Args args)
{
    UPSVendPriceAdmTrans        vendPriceAdmTrans;
    UPSVendPriceAdmSmartRound   vendPriceAdmSmartRound = UPSVendPriceAdmSmartRound::construct();
    FormDataSource              formDS;

    if (! args.dataset() == tablenum(UPSVendPriceAdmTrans))
    {
        throw error("@SYS18626");
    }

    vendPriceAdmTrans = args.record();

    if (! vendPriceAdmTrans.JournalNum)
    {
        throw error("@SYS59008");
    }

    vendPriceAdmSmartRound.setJournalNum(vendPriceAdmTrans.JournalNum);
    vendPriceAdmSmartRound.runOperation();

    if (args.record().isFormDataSource())
    {
        formDS = args.record().dataSource();
        formDS.research(true);
    }
}
